// Exact integer mirrors of src/lib/shocks.ts + planned planMath extensions.
const rhu = (n, d) => { if (d <= 0) throw new Error('den'); const s = n >= 0 ? 1 : -1; return s * Math.floor((Math.abs(n) + Math.floor(d / 2)) / d) }
const scaleCents = (base, pct) => rhu(base * pct, 100)
const CAP = 1200
function runway(buffer, oneOff, income, spending) {
  const bl = buffer - oneOff, gap = spending - income
  if (bl <= 0) return { state: 'buffer_depleted', deci: 0 }
  if (gap <= 0) return { state: 'no_shortfall', deci: CAP }
  return { state: 'finite', deci: Math.min(Math.floor((20 * bl + gap) / (2 * gap)), CAP) }
}
function goalPlan(I, S) {
  const target = 3 * S
  const floor = scaleCents(I, 5)
  const contribution = Math.max(I - S, floor)
  if (contribution <= 0) return { target, contribution, months: -1, cut: -1, status: 'needs income' }
  const months = Math.floor((target + contribution - 1) / contribution)
  const needsCut = I <= S
  const cut = needsCut ? S - I + contribution : 0
  return { target, contribution, months, cut, status: cut > 0 ? 'cut needed' : 'on track' }
}
const ceilDiv = (a, b) => (b <= 0 ? -1 : Math.floor((a + b - 1) / b))

// fixture accounts: id, I, F, S, B, H, P, ins
const FIX = [
  { id: '68257', I: 650326, F: 430672, S: 716084, B: 643785, H: 430672, P: 284493, ins: 0 },
  { id: '23838', I: 280403, F: 127553, S: 173780, B: 3229857, H: 127553, P: 0, ins: 0 },
  { id: '49900', I: 0, F: 0, S: 6293, B: 925140, H: 0, P: 0, ins: 0 },
  { id: '98952', I: 391520, F: 124407, S: 427376, B: 881382, H: 124407, P: 0, ins: 0 },
  { id: '42988', I: 1439203, F: 733100, S: 1593092, B: -73269, H: 632417, P: 473085, ins: 0 },
]

// COMBO twist: jobLoss + EI 55%, bills +15%, duration 6
const out = []
for (const f of FIX) {
  const gp = goalPlan(f.I, f.S)
  const milestones = [1, 2, 3, 6].map(k => ({ k, amount: k * f.S, monthsTo: ceilDiv(k * f.S, gp.contribution) }))
  // shocked
  const incomeAfter = scaleCents(f.I, 55)
  const billsDelta = scaleCents(f.H, 15)
  const spendingAfter = f.S + billsDelta
  const oneOff = 0
  const base = runway(f.B, oneOff, incomeAfter, spendingAfter)
  // lever ladder: shop_insurance (ins>0), trim_discretionary (disc>0), defer_loan (P>0)
  const disc = Math.max(0, f.S - (f.F + f.P))
  const effects = []
  if (f.ins > 0) effects.push({ id: 'shop_insurance', d: -f.ins })
  if (disc > 0) effects.push({ id: 'trim_discretionary', d: -disc })
  if (f.P > 0) effects.push({ id: 'defer_loan', d: -f.P })
  let spend = spendingAfter
  const steps = []
  for (const e of effects) {
    spend = Math.max(0, spend + e.d)
    const r = runway(f.B, oneOff, incomeAfter, spend)
    steps.push({ id: e.id, effect: e.d, spending: spend, gap: spend - incomeAfter, state: r.state, deci: r.deci, plusCum: r.deci - base.deci })
  }
  // backup plan
  const cutFloor = f.F + f.P
  const survives = base.state === 'no_shortfall' || (base.state === 'finite' && base.deci >= 60)
  const shortfall = base.state === 'buffer_depleted' ? 60 : (survives ? 0 : 60 - base.deci)
  out.push({ id: f.id, goal: gp, milestones, shocked: { incomeAfter, billsDelta, spendingAfter, gap: spendingAfter - incomeAfter }, base, ladder: steps, backup: { cutFloor, survives, shortfall } })
}
return JSON.stringify(out, null, 1)

